/// <summary>
/// Extension of clicked method
/// </summary>
public void clicked()
{
    MenuFunction    menuFunction;
    Args            args = new Args();
    ProjTable       locProjTable = element.projTable;

    next clicked();

    args.parm(locProjTable.ProjId);
    args.caller(element);

    menuFunction = new MenuFunction(menuitemDisplayStr(pmfBatchOrderNew), MenuItemType::Display);

    if (menuFunction && menuFunction.checkAccessRights())
    {
        menuFunction.run(args);
    }
}
